mapper.update:
UPDATE arte_platform_workspace SET
name=#{row.name},description=#{row.description},state=#{row.state},version=#{row.version},auth_epoch=#{row.authEpoch},updated_sec=#{row.updatedSec},updated_nano=#{row.updatedNano}
WHERE tenant_id=#{row.tenantId} AND id=#{row.id} AND version=#{expected} AND created_by=#{row.createdBy} AND
created_sec=#{row.createdSec} AND created_nano=#{row.createdNano} AND auth_epoch<=#{row.authEpoch}
AND (updated_sec<#{row.updatedSec} OR (updated_sec=#{row.updatedSec} AND updated_nano<=#{row.updatedNano}))

mapper.select:
SELECT w.* FROM arte_platform_workspace_member m JOIN arte_platform_workspace w ON w.tenant_id=m.tenant_id AND w.id=m.workspace_id WHERE m.subject_digest=#{digest} AND m.subject_id=#{subject}
AND (m.workspace_created_sec<#{key.createdSec} OR (m.workspace_created_sec=#{key.createdSec} AND m.workspace_created_nano<#{key.createdNano}) OR (m.workspace_created_sec=#{key.createdSec} AND m.workspace_created_nano=#{key.createdNano} AND (m.tenant_id>#{key.tenantId} OR (m.tenant_id=#{key.tenantId} AND m.workspace_id>#{key.id}))))
ORDER BY m.workspace_created_sec DESC,m.workspace_created_nano DESC,m.tenant_id,m.workspace_id LIMIT #{limit}
